import {calculateBudget,addSelection,isDifferent} from './core.js';
import {initGuide,comparisonExtras} from './guide.js';
let guideUI=null;

const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const won=value=>value!==null&&value!==undefined&&value!==''&&Number.isFinite(Number(value))?new Intl.NumberFormat('ko-KR').format(Number(value))+'원':'미확인';
const number=value=>new Intl.NumberFormat('ko-KR').format(value);
const unique=values=>[...new Set(values)];
const agencyStyles={'교원투어':['#426d5d','#e7eee6'],'노랑풍선':['#9b7629','#f5edd7'],'모두투어':['#39757a','#e5eeec'],'참좋은여행사':['#9c6557','#f3e8e2'],'하나투어':['#736397','#ece8f3']};
const shortAgency=agency=>({'교원투어':'교원','노랑풍선':'노랑','모두투어':'모두','참좋은여행사':'참좋은','하나투어':'하나'}[agency]||agency);
const manwon=value=>Number.isFinite(value)?(Math.round(value/1000)/10).toLocaleString('ko-KR')+'만':'미확인';
const agencyColor=agency=>agencyStyles[agency]?.[0]||'#245c4d';
const filterKeys=['agency','search','route','date','shopping','guide','dinner','onsen','maxPrice','sort'];
let catalog,differences,cardById,groupById,groupMin={};
let photoList=[],photoIndex=0;
const productCache=new Map();let toastTimer,compareVersion=0,detailVersion=0;
let sourceView={ids:[],file:null,limit:25};
const initial={agency:'all',search:'',route:'all',date:'all',shopping:'all',guide:'all',dinner:'all',onsen:false,maxPrice:2600000,sort:'price-asc',selected:[],diffOnly:false,category:'all',detailId:'F05',detailTab:'itinerary',budgetProduct:'F05',budget:{people:'1',singles:'0',rate:'',meal:'0',upgrade:'0',flightUpgrade:'0',other:'0',option:'0'},productExtras:{}};
let state=structuredClone(initial);
try{const saved=JSON.parse(localStorage.getItem('hokkaido-compare-v1')||'null');if(saved&&typeof saved==='object'){state={...initial,...saved,budget:{...initial.budget,...saved.budget},productExtras:{...saved.productExtras}};}}catch{}
const persist=()=>{try{localStorage.setItem('hokkaido-compare-v1',JSON.stringify(state));}catch{}};
const url=path=>new URL(path,import.meta.url).href;
async function json(path){const response=await fetch(url(path));if(!response.ok)throw new Error(`자료를 불러오지 못했습니다 (${response.status})`);return response.json();}
async function getProduct(id){if(!cardById[id])throw new Error('상품을 찾을 수 없습니다.');if(!productCache.has(id))productCache.set(id,json(cardById[id].detailPath));return productCache.get(id);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function showError(error){console.error(error);toast('자료를 불러오지 못했습니다. 연결 상태를 확인한 뒤 다시 시도해 주세요.');}
function badge(agency){const [color,bg]=agencyStyles[agency]||['#526952','#edf1e8'];return `<span class="agency-badge" style="--agency-color:${color};--agency-bg:${bg}">${esc(agency)}</span>`;}
function label(card){return shortAgency(card.agency)+card.fileNumber;}
function evidence(refs,text='원문 근거 ↗'){const ids=unique((refs||[]).filter(Boolean));return ids.length?`<button class="evidence-button" data-action="evidence" data-sources="${esc(ids.join(','))}">${esc(text)}</button>`:'';}
function statusClass(status){return status==='포함'?'status-included':status==='불포함'?'status-excluded':'status-unknown';}
function guideText(card){if(card.guide.status==='포함')return '가이드·기사 경비 포함';const fee=card.guide.value;if(card.guide.status==='불포함'&&fee)return `별도 ${number(fee.amount)}${fee.currency==='JPY'?'엔':'원'}`;return '필수경비 미확인';}
function photoButton(photo,className=''){return `<button class="photo-button ${className}" data-action="photo" data-photo="${esc(photo.id)}" aria-label="${esc(photo.label)} 사진 확대"><img src="${esc(photo.path)}" alt="${esc(photo.label)}" loading="lazy" decoding="async"><span class="photo-expand" aria-hidden="true">⤢</span></button>`;}
function initHero(){const picks=['F24-p9-i0','F24-p9-i6','F19-p12-i0','F28-p10-i2'].map(id=>catalog.photos.find(p=>p.id===id)).filter(Boolean);if(!picks.length)return;$('#heroVisual').innerHTML=`<div class="hero-mosaic">${picks.map((photo,i)=>`<button class="photo-button hero-tile tile-${i}" data-action="photo" data-photo="${esc(photo.id)}" aria-label="${esc(photo.label)} 확대"><img src="${esc(photo.path)}" alt="${esc(photo.label)}" ${i?'loading="lazy"':'fetchpriority="high"'} decoding="async"><span class="tile-caption">${esc(shortPhoto(photo))}</span></button>`).join('')}</div><span class="hero-caption">사진은 상품 PDF에 실린 참고사진 · 눌러서 크게 보기</span>`;}
const shortPhoto=photo=>photo.label.split(' · ')[0].replace(/\s*(원문|겨울|계절|야간)?\s*참고사진$/,'');
const dateRange=dates=>{const [a,b]=[dates[0],dates.at(-1)];if(!a)return '';const [y,m,d]=a.split('-'),[y2,m2,d2]=b.split('-');return y===y2&&m===m2?`${y}년 ${Number(m)}월 ${Number(d)}~${Number(d2)}일`:`${a}~${b}`;};
function renderSummary(){
 const cards=catalog.cards,count=(list)=>list.length,prices=cards.map(c=>c.price),min=Math.min(...prices),max=Math.max(...prices);
 const cheapest=cards.filter(c=>c.price===min),priciest=cards.filter(c=>c.price===max),agencies=unique(cards.map(c=>c.agency)),durations=unique(cards.map(c=>c.duration)),dates=unique(cards.map(c=>c.departure)).sort();
 const regionCount={};cards.forEach(c=>c.regions.forEach(r=>regionCount[r]=(regionCount[r]||0)+1));const topRegions=Object.entries(regionCount).sort((a,b)=>b[1]-a[1]).slice(0,3);
 const by=(fn)=>cards.filter(fn);const guideIn=by(c=>c.guide.status==='포함'),guideOut=by(c=>c.guide.status==='불포함'),guideUnknown=by(c=>c.guide.status==='미확인'),noShop=by(c=>c.shopping===0),oneShop=by(c=>c.shopping===1),d3=by(c=>c.dinnersIncluded===3),d2=by(c=>c.dinnersIncluded===2),d0=by(c=>c.dinnersIncluded===0),onsen=by(c=>c.onsenMention),free=by(c=>c.style==='자유여행형');
 $('#heroStats').innerHTML=`<span><strong>${cards.length}</strong>개 상품</span><span><strong>${agencies.length}</strong>개 여행사</span><span><strong>${catalog.groups.length}</strong>가지 코스</span><span><strong>${manwon(min).replace('만','')}~${manwon(max)}</strong>원</span>`;
 const tile=(icon,title,main,sub,key)=>`<div class="diff-tile" data-tile="${key}"><span class="diff-icon" aria-hidden="true">${icon}</span><span class="diff-title">${title}</span><strong>${main}</strong><small>${sub}</small></div>`;
 $('#quickSummary').innerHTML=`<div class="summary-head"><span class="summary-kicker">💡 30초 요약</span><span class="summary-asof">자료 기준 ${esc(catalog.as_of||'')}</span></div><p class="summary-lead">${cards.length}개 상품이 모두 <mark>${esc(durations.join('·'))}</mark>, ${esc(dateRange(dates))} 출발입니다. ${topRegions.map(([r,n])=>`${esc(r)}(${n})`).join('·')}처럼 이름난 곳은 대부분 겹치므로, 실제 차이는 <mark>코스 구성 · 가이드·기사 경비 · 쇼핑 · 저녁 포함 · 호텔</mark>에서 납니다.</p><div class="diff-tiles">${tile('₩','표시가 폭',`${manwon(min)} ~ ${manwon(max)}원`,`최저 ${cheapest.map(label).join('·')} / 최고 ${priciest.map(label).join('·')}`,'price')}${tile('🧳','가이드·기사 경비',`포함 ${count(guideIn)} · 별도 ${count(guideOut)}`,`미확인 ${count(guideUnknown)} · 별도면 현지에서 추가 지불`,'guide')}${tile('🛍️','쇼핑센터',`없음 ${count(noShop)} · 1회 ${count(oneShop)}`,`쇼핑 없는 상품: ${noShop.map(label).join('·')||'없음'}`,'shopping')}${tile('🍽️','저녁 포함 확인',`3회 ${count(d3)} · 2회 ${count(d2)}`,`${count(d0)?`포함 확인 없음 ${count(d0)} · `:''}2회면 하루 저녁은 불포함·미확인`,'dinner')}${tile('♨','온천 안내',`있음 ${count(onsen)}개`,`${count(free)?`자유여행 ${count(free)}개 · `:''}호텔은 모두 예정·후보`,'onsen')}</div>`;
 const options=catalog.cards.filter(c=>/미확인|상충|선택 가능/.test(c.optionsStatus||''));
 const foods=unique(catalog.cards.flatMap(c=>c.mealTags||[]));
 $('#quickSummary .diff-tiles').insertAdjacentHTML('beforeend',tile('🥢','구체 음식 안내',foods.filter(t=>t!=='주류무제한').join(' · ')||'미확인','날짜별 메뉴·포함 여부를 끼니 비교에서 확인','food')+tile('＋','옵션·필수경비 확인',options.length+'개 옵션 확인 필요',options.map(label).join(' · ')+' / 별도 가이드비 '+guideOut.length+'개','options'));
 const hotelCities=unique(cards.flatMap(c=>c.hotels.flatMap(h=>h.cities||[])));
 $('#quickSummary .diff-tiles').insertAdjacentHTML('beforeend',tile('⌂','숙박도시·호텔',esc(hotelCities.slice(0,4).join(' · ')),'후보 도시 기준 · 호텔은 예정 / 성급·객실·시설은 각각 확인','hotel'));
 const firstBy=(list,n=4)=>[...list].sort((a,b)=>a.price-b.price).slice(0,n);
 const picks=[{key:'cheap',title:'가장 적은 돈',apply:{sort:'price-asc'},ids:firstBy(cards,3),note:'표시가 낮은 순'},{key:'noshop',title:'쇼핑센터는 싫다',apply:{shopping:'0'},ids:noShop},{key:'guide',title:'가이드비까지 상품가에',apply:{guide:'포함'},ids:guideIn},{key:'dinner',title:'저녁 3번 모두 포함',apply:{dinner:'3'},ids:d3},...(free.length?[{key:'free',title:'일정은 자유롭게',apply:{route:free[0].group},ids:free}]:[])];
 $('#quickPicks').innerHTML=picks.map(p=>{const shown=firstBy(p.ids);return `<button class="pick-row" data-action="pick" data-pick="${p.key}" data-apply='${esc(JSON.stringify(p.apply))}'><span class="pick-title">${esc(p.title)}<small>${p.note||`${p.ids.length}개 상품`}</small></span><span class="pick-ids">${shown.map(c=>`<span class="mini-label" style="--agency-color:${agencyColor(c.agency)}">${esc(label(c))}</span>`).join('')}${p.ids.length>shown.length?`<span class="more">+${p.ids.length-shown.length}</span>`:''}</span><span class="pick-arrow" aria-hidden="true">›</span></button>`;}).join('');
 const used=new Set();
 $('#routeOverview').innerHTML=catalog.groups.map(g=>{const members=cards.filter(c=>c.group===g.route_group_id);const photo=catalog.photos.find(p=>p.kind==='site'&&p.route_groups.includes(g.route_group_id)&&!used.has(p.id))||catalog.photos.find(p=>p.kind==='site'&&p.route_groups.includes(g.route_group_id));if(photo)used.add(photo.id);const low=Math.min(...members.map(c=>c.price));return `<button class="route-card" data-action="route" data-route="${g.route_group_id}">${photo?`<span class="route-photo"><img src="${esc(photo.path)}" alt="" loading="lazy" decoding="async"><small>${esc(shortPhoto(photo))}</small></span>`:`<span class="route-photo empty"><span>${esc(g.core_regions.slice(0,2).join(' · '))}</span><small>관련 사진 없음</small></span>`}<span class="route-body"><strong>${esc(g.label)}</strong><span class="route-meta">${members.length}개 · ${manwon(low)}원부터</span><span class="route-dots">${unique(members.map(c=>c.agency)).map(a=>`<i style="--agency-color:${agencyColor(a)}" title="${esc(a)}"></i>`).join('')}</span></span></button>`;}).join('');
}
function applyPick(apply){for(const key of filterKeys)state[key]=initial[key];Object.assign(state,apply);persist();initFilters();renderCards();if(['shopping','guide','dinner','onsen','date','maxPrice'].some(k=>apply[k]!==undefined))$('#moreFilters').open=true;$('#browse').scrollIntoView({behavior:'smooth'});}
function initFilters(){
 const agencies=Object.keys(agencyStyles);$('#agencyTabs').innerHTML=['all',...agencies].map(a=>`<button class="agency-tab ${state.agency===a?'active':''}" data-action="agency" data-agency="${a}" aria-pressed="${state.agency===a}" style="--agency-color:${agencyStyles[a]?.[0]||'#abc2a4'}">${a==='all'?'':`<span class="dot"></span>`}${a==='all'?'전체 상품':esc(a)} <small>${a==='all'?catalog.cards.length:catalog.cards.filter(c=>c.agency===a).length}</small></button>`).join('');
 $('#routeChips').innerHTML=[{route_group_id:'all',label:'모든 코스'},...catalog.groups].map(g=>{const n=g.route_group_id==='all'?catalog.cards.length:catalog.cards.filter(c=>c.group===g.route_group_id).length;const on=state.route===g.route_group_id;return `<button class="route-chip ${on?'active':''}" data-action="route" data-route="${g.route_group_id}" aria-pressed="${on}">${esc(g.label)} <small>${n}</small></button>`;}).join('');
 $('#routeFilter').innerHTML='<option value="all">모든 코스</option>'+catalog.groups.map(g=>`<option value="${g.route_group_id}">${esc(g.label)}</option>`).join('');
 $('#dateFilter').innerHTML='<option value="all">가능한 날짜 모두</option>'+unique(catalog.cards.map(c=>c.departure)).sort().map(d=>`<option value="${d}">${d} 출발</option>`).join('');
 const options=catalog.cards.map(c=>`<option value="${c.id}">${esc(label(c))} · ${won(c.price)} · ${esc(groupById[c.group].label)}</option>`).join('');$('#budgetProduct').innerHTML=options;$('#detailProduct').innerHTML=options;
 syncFilterValues();syncBudgetValues();$('#budgetProduct').value=state.budgetProduct;$('#detailProduct').value=state.detailId;$('#referenceStatus').textContent=catalog.reference_status;
}
function syncFilterValues(){for(const [selector,key] of [['#searchInput','search'],['#routeFilter','route'],['#dateFilter','date'],['#shoppingFilter','shopping'],['#guideFilter','guide'],['#dinnerFilter','dinner'],['#sortSelect','sort'],['#maxPrice','maxPrice']])$(selector).value=state[key];$('#onsenFilter').checked=state.onsen;$('#maxPriceLabel').textContent=state.maxPrice>=2600000?'전체':won(state.maxPrice);$('#differencesOnly').checked=state.diffOnly;$('#compareCategory').value=state.category;$('#detailProduct').value=state.detailId;$('#budgetProduct').value=state.budgetProduct;}
function renderCards(){
 const query=state.search.toLocaleLowerCase('ko').trim();let rows=catalog.cards.filter(c=>(state.agency==='all'||c.agency===state.agency)&&(state.route==='all'||c.group===state.route)&&(state.date==='all'||c.departure===state.date)&&(state.shopping==='all'||String(c.shopping)===state.shopping)&&(state.guide==='all'||c.guide.status===state.guide)&&(state.dinner==='all'||String(c.dinnersIncluded)===state.dinner)&&(!state.onsen||c.onsenMention)&&c.price<=state.maxPrice&&(!query||c.search.toLocaleLowerCase('ko').includes(query)));
 rows.sort((a,b)=>state.sort==='price-desc'?b.price-a.price:state.sort==='agency'?a.agency.localeCompare(b.agency,'ko')||a.price-b.price:state.sort==='date'?a.departure.localeCompare(b.departure)||a.price-b.price:a.price-b.price);
 $('#resultCount').innerHTML=`전체 ${catalog.cards.length}개 중 <strong>${rows.length}개</strong> 상품 ${state.date==='all'?'<span class="soft-note">· 출발일 전체</span>':''}`;renderActiveFilters();
 $('#productGrid').innerHTML=rows.length?rows.map(c=>{const selected=state.selected.includes(c.id);return `<article class="product-card ${selected?'selected':''}" data-card="${c.id}" style="--agency-color:${agencyStyles[c.agency]?.[0]||'#245c4d'}"><div class="card-top">${badge(c.agency)}<span class="file-code">${esc(label(c))}</span></div><div class="card-route">${esc(groupById[c.group].label)}</div><h3 title="${esc(c.name)}">${esc(c.name)}</h3><div class="region-tags" aria-label="확인된 방문 지역">${c.regions.map(r=>`<span>${esc(r)}</span>`).join('')}</div><div class="card-dates"><span>${esc(c.departure)} 출발</span><span>${esc(c.duration)}</span><span>${esc(c.airline||'항공사 미확인')}</span></div><div class="card-price"><strong>${won(c.price)}</strong><span>/ 성인 1인 표시가</span>${c.price===groupMin[c.group]&&groupById[c.group].member_ids.length>1?'<span class="best-flag">이 코스 최저</span>':''}</div><p class="cost-note ${c.guide.status==='불포함'?'cost-risk':c.guide.status==='미확인'?'cost-unknown':''}">${esc(guideText(c))}${c.guide.status==='불포함'?' · 상품가 외 필수경비':''} ${evidence(c.guide.sources,'경비 근거')}</p><div class="card-tags"><span class="tag ${c.shopping===0?'green':''}">${c.shopping===null?'쇼핑 미확인':c.shopping===0?'쇼핑 없음':'쇼핑 '+c.shopping+'회'}</span><span class="tag">${c.style==='자유여행형'?'자유여행':c.onsenMention?'온천 안내 있음':'온천 유무 확인'}</span><span class="tag ${c.dinnersIncluded===3?'green':''}">석식 ${c.dinnersIncluded}회 포함 확인</span>${c.guide.status==='포함'?'<span class="tag green">가이드비 포함</span>':''}</div><div class="card-hotel"><span class="hotel-head">숙박 · 예정호텔</span>${c.hotels.map(h=>`<span title="${esc(h.names.join(' / '))}"><b>${h.day}박째</b>${esc(h.names[0]||'호텔 미확인')}${h.names.length>1?' 외 후보':''}</span>`).join('')}</div><div class="card-actions"><button class="button quiet" data-action="detail" data-id="${c.id}">상품 자세히 ↗</button><button class="button select-button" data-action="select" data-id="${c.id}" aria-pressed="${selected}">${selected?'✓ 선택됨':'+ 비교 선택'}</button></div></article>`;}).join(''):'<div class="empty-state"><h3>조건에 맞는 상품이 없습니다</h3><p>검색어나 필터를 줄여보세요.</p><button class="button quiet" data-action="reset" style="margin-top:16px">필터 초기화</button></div>';
}
function renderActiveFilters(){
 const chips=[];const add=(key,text)=>chips.push(`<button class="filter-chip" data-action="clear-filter" data-key="${key}">${esc(text)} <span aria-hidden="true">✕</span><span class="sr-only">조건 해제</span></button>`);
 if(state.agency!=='all')add('agency',state.agency);if(state.route!=='all')add('route',groupById[state.route]?.label||state.route);if(state.search.trim())add('search',`“${state.search.trim()}”`);if(state.date!=='all')add('date',state.date+' 출발');if(state.shopping!=='all')add('shopping',state.shopping==='0'?'쇼핑 없음':'쇼핑 '+state.shopping+'회');if(state.guide!=='all')add('guide','가이드비 '+state.guide);if(state.dinner!=='all')add('dinner',state.dinner==='0'?'석식 포함 확인 없음':'석식 '+state.dinner+'회 포함');if(state.onsen)add('onsen','온천 안내');if(state.maxPrice<2600000)add('maxPrice',won(state.maxPrice)+' 이하');
 $('#activeFilters').innerHTML=chips.length?chips.join('')+'<button class="text-link" data-action="reset">모두 해제</button>':'';
 const more=['date','shopping','guide','dinner'].filter(k=>state[k]!=='all').length+(state.onsen?1:0)+(state.maxPrice<2600000?1:0);$('#activeFilterCount').textContent=more?more+'개 적용':'';
 document.querySelectorAll('.route-chip').forEach(b=>{const on=b.dataset.route===state.route;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on));});
}
function renderTray(){const ids=state.selected;$('#selectionCount').textContent=ids.length;$('#selectedChips').innerHTML=ids.length?ids.map(id=>`<span class="selected-chip">${esc(label(cardById[id]))}<button data-action="remove" data-id="${id}" aria-label="${esc(label(cardById[id]))} 비교에서 제거">✕</button></span>`).join(''):'<span class="soft-note">마음에 드는 상품에 +</span>';$('#goCompare').disabled=!ids.length;}
function changeSelection(ids){state.selected=unique(ids).filter(id=>cardById[id]).slice(0,4);persist();renderTray();renderCards();renderCompare().catch(showError);renderBudget();guideUI?.syncSelection();}
function selectProduct(id){const result=addSelection(state.selected,id,catalog.cards.map(c=>c.id));if(result.error){toast(result.error);return;}changeSelection(result.ids);toast(label(cardById[id])+' 상품을 비교에 담았어요.');}
function sourceText(product,refs,max=3){return unique((refs||[]).map(id=>product.source_index[id]?.quote).filter(Boolean)).slice(0,max).join('\n');}
const cell=(text,sources=[],note='')=>({text:text??'미확인',sources:unique(sources||[]),note});
function getFields(){
 const fields=[];const add=(key,label,category,getter)=>fields.push({key,label,category,getter});
 add('price','성인 1인 표시가','cost',p=>cell(won(p.adult_price.value),p.adult_price.sources,'원문 표시가 · 현재가·예약 확정금액 아님'));
 add('guide','가이드·기사 경비','cost',p=>cell(guideText(cardById[p.comparison_id]),p.costs.guide_driver.sources));
 add('shopping','쇼핑센터','tour',p=>cell(p.shopping.count.value===null?'미확인':`${p.shopping.count.value}회`,p.shopping.count.sources));
 for(let d=0;d<3;d++)add('hotel'+d,`${d+1}박째 호텔 후보`,'hotel',p=>cell(p.days[d].hotel.candidates.map(h=>h.name.value).join('\n또는 ')||'미확인',p.days[d].hotel.candidates.flatMap(h=>h.name.sources),'예정 · 동급 대체 가능'));
 for(let d=0;d<3;d++)add('dinner'+d,`${d+1}일차 석식`,'meal',p=>mealCell(p.days[d].meals.dinner));
 add('route','코스 중심 지역','tour',p=>cell(Object.keys(p.route.core_regions).join(' · '),Object.values(p.route.core_regions).flat()));
 add('duration','여행기간','tour',p=>cell(p.duration.value.label,p.duration.sources));
 add('departure','출발일','tour',p=>cell(p.departure_date.value,p.departure_date.sources,'가능 기간에서 골라둔 출발일별 후보'));
 add('airline','항공사','tour',p=>cell(p.airline.value||'미확인',p.airline.sources));
 for(let i=0;i<2;i++)add('flight'+i,i?'귀국 항공':'출국 항공','tour',p=>{const f=p.flights[i];return cell(`${f.flight_number.value||'미확인'}\n${f.departure_time.value||'미확인'} → ${f.arrival_time.value||'미확인'}`,[...f.flight_number.sources,...f.departure_time.sources,...f.arrival_time.sources],'원문 현지 시각 / 항공 변경 가능');});
 for(let d=0;d<3;d++){
  add('hotelgrade'+d,`${d+1}박째 성급`,'hotel',p=>cell(p.days[d].hotel.candidates.map(h=>`${h.name.value}: ${h.grade.value||'미확인'}`).join('\n'),p.days[d].hotel.candidates.flatMap(h=>h.grade.sources),'특급·온천을 5성급으로 환산하지 않음'));
  add('onsen'+d,`${d+1}박째 온천·욕장`,'hotel',p=>{const h=p.days[d].hotel;return cell(`온천: ${facilityText(h.onsen_status,'온천')}\n대욕장: ${facilityText(h.public_bath_status,'대욕장')}\n노천탕: ${facilityText(h.open_air_bath_status,'노천탕')}`,[...(h.onsen_status?.sources||[]),...(h.public_bath_status?.sources||[]),...(h.open_air_bath_status?.sources||[])],'일차별 원문 시설 안내 · 모든 후보의 공통 시설 아님');});
  add('room'+d,`${d+1}박째 객실`,'hotel',p=>cell(p.days[d].hotel.room_conditions.map(v=>v.value).filter(Boolean).slice(0,3).join('\n')||'미확인',p.days[d].hotel.room_conditions.flatMap(v=>v.sources),'원문 객실 조건 · 최종 배정 별도 확인'));
 }
 for(let d=0;d<4;d++)for(const [key,name] of [['breakfast','조식'],['lunch','중식'],['dinner','석식']])if(!(key==='dinner'&&d<3))add(key+d,`${d+1}일차 ${name}`,'meal',p=>mealCell(p.days[d].meals[key]));
 add('visit','쇼핑 방문 의무','tour',p=>cell(p.shopping.visit_obligation.value||'미확인',p.shopping.visit_obligation.sources));
 add('purchase','쇼핑 구매 의무','tour',p=>cell(p.shopping.purchase_obligation.value||'미확인',p.shopping.purchase_obligation.sources,'방문과 구매 의무는 별개'));
 add('options','선택관광','tour',p=>cell(p.optional_tours.status,p.optional_tours.sources,p.optional_tours.status==='선택 가능'?'개별 옵션 이름·가격 미확인':''));
 add('admission','관광지 입장료','tour',p=>cell(sourceText(p,p.tour_admission.global_policy.sources,2)||'개별 입장료 미확인',p.tour_admission.global_policy.sources,'일반 포함정책과 개별 예외 구분 · 무료입장 뜻 아님'));
 add('single','1인실 추가요금','cost',p=>{const s=p.costs.single_room.amount;const conflict=p.costs.single_room.conflict;return cell(conflict?'240,000원 / 280,000원 · 원문 상충':s.value?`${number(s.value.amount)} ${s.value.currency}`:'미확인',conflict?conflict.sources:s.sources,conflict?conflict.note:'상품가 외 · 원문의 적용 단위 확인');});
 add('fuel','유류할증료','cost',p=>{const s=p.costs.fuel_surcharge;return cell(s.value===null?'금액 미확인':`${won(s.value)} · ${s.status}`,s.sources,s.components||'표시가 포함 여부와 변동조건 확인');});
 add('tax','세금','cost',p=>{const s=p.costs.taxes;return cell(s.value===null?'개별 금액 미확인':won(s.value),s.sources,'세금·유류 합산액은 임의로 분리하지 않음');});
 add('min','최소 출발인원','terms',p=>cell(p.minimum_departure_people.value===null?'미확인':p.minimum_departure_people.value+'명',p.minimum_departure_people.sources,'출발 확정·실제 단체 규모를 뜻하지 않음'));
 add('deposit','예약금','terms',p=>cell(p.terms.deposit.value===null?'미확인':won(p.terms.deposit.value),p.terms.deposit.sources));
 add('termstype','적용 약관','terms',p=>cell(p.terms.type.value,p.terms.type.sources));
 add('cancel','취소 규정 상태','terms',p=>cell(p.terms.cancellation_status,p.terms.sources));
 for(let d=0;d<4;d++)add('move'+d,`${d+1}일차 이동`,'tour',p=>{const t=p.days[d].transport;const stated=t.segments.filter(x=>x.stated_minutes!==null);return cell(stated.length?stated.map(s=>`${s.segment.value} / ${s.display_duration}`).join('\n'):'이동시간 미확인',stated.flatMap(s=>s.sources),'명시 구간만 표시 · 하루 전체 이동·관광시간 미확인');});
 return fields.concat(comparisonExtras({cell,sourceText}),[{key:'estimate',label:'입력 가정에 따른 예상경비',category:'cost',getter:p=>{const c=cardById[p.comparison_id],calc=calculateBudget(c,{...state.budget,productExtra:state.productExtras[c.id]??0});return cell(calc.valid?won(calc.estimateKRW)+(calc.currencyConversionPending?' + '+number(calc.yenTotal)+'엔 별도':''):'입력값 확인 필요',p.adult_price.sources,'일행 '+state.budget.people+'인 기준 · 확정견적 아님 · 미확인 비용 별도');}}]);
}
function mealCell(meal){return cell((meal.value||'미확인')+' · '+meal.status,meal.sources,meal.status==='미확인'?'포함 여부 미확인':meal.status);}
function facilityText(value,kind){if(!value||value.value===null)return '미확인';if(value.value===false)return kind==='온천'?'온천 아님(명시)':'불포함';return '기재 있음 · 후보별 확인';}
async function renderCompare(){const version=++compareVersion;const ids=[...state.selected];$('#compareEmpty').hidden=!!ids.length;$('#comparisonContent').hidden=!ids.length;if(!ids.length)return;$('#comparisonTable').innerHTML='<tbody><tr><td>선택 상품의 상세 조건을 불러오고 있습니다.</td></tr></tbody>';const products=await Promise.all(ids.map(getProduct));if(version!==compareVersion)return;
 let fields=getFields().map(field=>({...field,cells:products.map(field.getter)}));fields.forEach(f=>f.different=isDifferent(f.cells.map(c=>c.text)));
 if(state.category!=='all')fields=fields.filter(f=>f.category===state.category);if(state.diffOnly&&ids.length>1)fields=fields.filter(f=>f.different);fields.sort((a,b)=>Number(b.different)-Number(a.different));
 renderCompareSummary(products);renderStayMeal(products);
 const narrow=innerWidth<581,labelWidth=narrow?96:140,colWidth=narrow?172:230;
 $('#comparisonTable').style.minWidth=(labelWidth+products.length*colWidth)+'px';
 $('#comparisonTable').innerHTML=`<colgroup><col style="width:${labelWidth}px">${products.map(()=>`<col style="min-width:${colWidth-10}px">`).join('')}</colgroup><thead><tr><th scope="col">비교 항목<br><small>${state.diffOnly?'차이만 보기':'다른 조건 먼저'}</small></th>${products.map(p=>{const c=cardById[p.comparison_id];return `<th scope="col" class="agency-col" style="--agency-color:${agencyColor(c.agency)}"><div class="table-product">${badge(c.agency)}<span>${esc(label(c))} · ${esc(c.departure)}</span><strong>${esc(c.name)}</strong><span class="table-price">${won(c.price)}</span><button class="remove-button" data-action="remove" data-id="${c.id}">비교에서 제거</button><button class="evidence-button" data-action="detail" data-id="${c.id}">일정·호텔 자세히 ↗</button></div></th>`;}).join('')}</tr></thead><tbody>${fields.length?fields.map(f=>`<tr class="${f.different?'different':''}" data-field="${f.key}"><th scope="row">${esc(f.label)}${f.different?'<span class="diff-mark">다른 조건</span>':''}</th>${f.cells.map(c=>`<td><div class="cell-text">${esc(c.text)}</div>${c.note?`<div class="cell-status">${esc(c.note)}</div>`:''}${evidence(c.sources)}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${ids.length+1}">선택한 항목에서 표시상 차이가 없습니다. 미확인 값이 같아도 실제 조건이 같다는 뜻은 아닙니다.</td></tr>`}</tbody>`;
 const pair=ids.length===2?differences.pairs.find(p=>[p.left_id,p.right_id].every(id=>ids.includes(id))):null;$('#pairExplanation').innerHTML=pair?`<div class="pair-explanation"><p><strong>${esc(label(cardById[pair.left_id]))} ↔ ${esc(label(cardById[pair.right_id]))}</strong> · ${esc(pair.explanation.text.replaceAll(/F\d{2}/g,id=>cardById[id]?label(cardById[id]):id))}</p>${evidence(pair.explanation.sources,'차이점의 원문 근거 ↗')}</div>`:'';
}
function guideShort(c){if(c.guide.status==='포함')return '포함';const fee=c.guide.value;if(c.guide.status==='불포함'&&fee)return fee.currency==='JPY'?number(fee.amount)+'엔':manwon(fee.amount)+'원';return '미확인';}
function renderCompareSummary(products){
 const cs=products.map(p=>cardById[p.comparison_id]);const minPrice=Math.min(...cs.map(c=>c.price));const maxDinner=Math.max(...cs.map(c=>c.dinnersIncluded));const multi=cs.length>1;
 const rows=[
  {label:'표시가',vals:cs.map(c=>({t:manwon(c.price),s:c.price===minPrice?(multi?'가장 낮음':''):'+'+manwon(c.price-minPrice),good:multi&&c.price===minPrice}))},
  {label:'가이드·기사 경비',vals:cs.map(c=>({t:guideShort(c),s:c.guide.status==='불포함'?'현지 별도':c.guide.status==='미확인'?'확인 필요':'상품가 포함',good:c.guide.status==='포함',warn:c.guide.status!=='포함'}))},
  {label:'쇼핑센터',vals:cs.map(c=>({t:c.shopping===null?'미확인':c.shopping===0?'없음':c.shopping+'회',good:c.shopping===0}))},
  {label:'저녁 포함 확인',vals:cs.map(c=>({t:c.dinnersIncluded+'회',s:'3박 중',good:multi&&maxDinner>0&&c.dinnersIncluded===maxDinner}))},
  {label:'온천 안내',vals:cs.map(c=>({t:c.style==='자유여행형'?'자유여행':c.onsenMention?'있음':'확인 필요',good:c.onsenMention}))},
  {label:'코스',vals:cs.map(c=>({t:c.regions.join('·'),small:true}))},
  {label:'출발 · 항공',vals:cs.map(c=>({t:c.departure.slice(5).replace('-','.')+' 출발',s:c.airline||'항공 미확인'}))}
 ];
 rows.forEach(r=>r.diff=multi&&new Set(r.vals.map(v=>v.t)).size>1);const diffCount=rows.filter(r=>r.diff).length;
 $('#compareSummary').innerHTML=`<div class="block-head"><h3>핵심 차이 한눈에</h3><p>${multi?`7가지 핵심 항목 중 <strong>${diffCount}가지</strong>가 다릅니다. <span class="good-key">초록</span>은 상대적으로 유리한 조건입니다.`:'상품을 하나 더 고르면 차이가 강조됩니다.'}</p></div><div class="key-table-wrap"><table class="key-table" style="--cols:${cs.length}"><thead><tr><th scope="col"><span class="sr-only">항목</span></th>${cs.map(c=>`<th scope="col" style="--agency-color:${agencyColor(c.agency)}"><strong class="key-agency">${esc(label(c))}</strong><small>${esc(c.departure.slice(5).replace('-','.'))}</small></th>`).join('')}</tr></thead><tbody>${rows.filter(r=>!state.diffOnly||!multi||r.diff).map(r=>`<tr class="${r.diff?'differs':''}"><th scope="row">${esc(r.label)}${r.diff?'<span class="diff-dot" title="다른 조건">차이</span>':''}</th>${r.vals.map(v=>`<td class="${v.good&&r.diff?'good':''} ${v.warn&&r.diff?'warn':''} ${v.small?'small':''}"><b>${esc(v.t)}</b>${v.s?`<small>${esc(v.s)}</small>`:''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function facilityChips(h){const items=[['온천',h.onsen_status],['대욕장',h.public_bath_status],['노천탕',h.open_air_bath_status]].filter(([,v])=>v&&v.value!==null&&v.value!==undefined);return items.length?items.map(([kind,v])=>v.value===false?`<span class="fac no">${kind==='온천'?'온천 아님(명시)':kind+' 불포함'}</span>`:`<span class="fac yes">${kind==='온천'?'♨ ':''}${kind} 안내</span>`).join(''):'<span class="fac unknown">시설 미확인</span>';}
function renderStayMeal(products){
 const nights=Math.min(3,...products.map(p=>p.days.length));
 $('#stayMeal').innerHTML=`<div class="block-head"><h3>밤마다 비교 · 호텔·온천·저녁</h3><p>같은 1박째라도 온천 호텔인지, 저녁이 포함되는지에 따라 여행의 질이 달라집니다. 호텔은 모두 예정이며 동급 대체될 수 있습니다.</p></div><div class="night-grid">${Array.from({length:nights},(_,d)=>`<section class="night-block" aria-label="${d+1}박째"><h4><span class="night-no">${d+1}박</span>${d+1}일차 밤</h4>${products.map(p=>{const c=cardById[p.comparison_id],day=p.days[d],h=day.hotel,names=h.candidates.map(x=>x.name.value).filter(Boolean),dinner=day.meals.dinner,photo=hotelPhoto(names.slice(0,1));return `<div class="stay-row" style="--agency-color:${agencyColor(c.agency)}"><span class="stay-label">${esc(label(c))}</span><div class="stay-main"><div class="stay-hotel">${photo?`<button class="stay-thumb" data-action="photo" data-photo="${esc(photo.id)}" aria-label="${esc(photo.label)} 확대"><img src="${esc(photo.path)}" alt="" loading="lazy"></button>`:''}<div><b>${esc(names[0]||'호텔 미확인')}</b>${names.length>1?`<small> 외 ${names.length-1}곳 후보</small>`:''}<div class="fac-row">${facilityChips(h)}</div></div></div><div class="stay-dinner"><span class="meal-key">저녁</span><span class="meal-text">${esc(dinner.value||'미확인')}</span><span class="tag ${dinner.status==='포함'?'green':dinner.status==='불포함'?'amber':'gray'}">${esc(dinner.status)}</span></div></div></div>`;}).join('')}</section>`).join('')}</div><p class="fine-print">시설 표시는 해당 일차 원문 안내 기준이며 모든 대체 후보의 공통 시설이 아닙니다. 사진은 그 호텔 이름과 일치하는 PDF 사진만 연결했습니다.</p>`;
}
const budgetIds={travelerCount:'people',singleCount:'singles',exchangeRate:'rate',mealBudget:'meal',upgradeBudget:'upgrade',otherBudget:'other',optionBudget:'option',flightUpgradeBudget:'flightUpgrade'};
function syncBudgetValues(){for(const [id,key]of Object.entries(budgetIds))$('#'+id).value=state.budget[key]??initial.budget[key];}
function renderBudget(){const ids=state.selected.length?state.selected:[state.budgetProduct];$('#budgetScope').textContent=state.selected.length?`선택한 ${ids.length}개 상품에 같은 가정을 적용합니다.`:'선택 상품이 없으면 위 상품으로 계산합니다.';$('#budgetProduct').disabled=!!state.selected.length;$('#budgetProduct').value=ids[0];let errors=[];$('#budgetResults').innerHTML=ids.map(id=>{const c=cardById[id];if(!c)return '';const calc=calculateBudget(c,{...state.budget,productExtra:state.productExtras[id]??0});if(!calc.valid){errors.push(...calc.errors);return `<article class="budget-card" data-budget-id="${id}">${badge(c.agency)}<h3>${esc(label(c))}</h3><p class="field-error">입력값을 확인해 주세요.</p><label class="per-product-budget">이 상품에만 더할 예상액 (1인·원)<input type="number" min="0" max="10000000" data-product-extra="${id}" value="${esc(state.productExtras[id]??0)}" aria-label="${esc(label(c))} 상품별 추가 예상액"></label></article>`;}const pending=calc.currencyConversionPending;return `<article class="budget-card" data-budget-id="${id}">${badge(c.agency)}<h3>${esc(label(c))} · ${esc(groupById[c.group].label)}</h3><span class="tag gray">${calc.people}인 기준 · 예약 확정금액 아님</span><p class="budget-title">가정을 더한 예상액</p><div class="budget-total" data-total-for="${id}">${won(calc.estimateKRW)}</div><div class="budget-per-person">1인 평균 예상액 <b>${won(Math.round(calc.perPersonKRW))}</b> <small>원화 부분합 ÷ 인원 · 엔화 미환산 시 별도</small></div><div class="budget-jpy">${pending?`+ ${number(calc.yenTotal)}엔 · 환율 미입력`:(calc.yenTotal?`${number(calc.yenTotal)}엔을 가정 환율 ${calc.rate}원으로 환산`:'엔화 별도 입력액 없음')}</div><div class="budget-breakdown"><div><span>상품 표시가 × ${calc.people}인</span><b>${won(calc.base)}</b></div><div><span>기재된 가이드·기사 추가경비</span><b>${calc.guideJPY?number(calc.guideJPY)+'엔':calc.guideKRW?won(calc.guideKRW):c.guide.status==='포함'?'상품가 포함':'미확인'}</b></div><div><span>1인실 × ${calc.singles}인</span><b>${calc.singles?(c.single.value?(calc.singleJPY?number(calc.singleJPY)+'엔':won(calc.singleKRW)):'요금 미확인'):'사용 인원 0명'}</b></div><div class="rule"><span>자료상 확인 원화 부분합</span><b>${won(calc.documentedKRW)}</b></div><div><span>내가 입력한 원화 가정</span><b>${won(calc.assumedKRW)}</b></div><div><span>내가 입력한 현지비 가정</span><b>${number(calc.assumedJPY)}엔</b></div>${calc.convertedJPY!==null&&calc.yenTotal?`<div><span>가정 환율로 환산한 엔화 합계</span><b>${won(calc.convertedJPY)}</b></div>`:''}</div><div class="cost-sections"><section><b>① 원문 기재 필수 금액</b><span>${won(calc.requiredKRW)}${calc.requiredJPY?' + '+number(calc.requiredJPY)+'엔':''}</span><small>표시가 + 명시 가이드·기사 경비 / 예약 확정가 아님</small></section><section><b>② 선택 시 기재 금액</b><span>${won(calc.conditionalKRW)}${calc.conditionalJPY?' + '+number(calc.conditionalJPY)+'엔':''}</span><small>1인실 ${calc.singles}인 · 요금 미확인은 별도 확인</small></section><section><b>③ 직접 입력한 가정</b><span>${won(calc.assumedKRW)} + ${number(calc.assumedJPY)}엔</span><small>항공·호텔 변경, 식비, 개인 예산, 선택관광</small></section></div>${c.singleConflict?`<p class="info-note warn-text">${esc(c.singleConflict.note)} ${evidence(c.singleConflict.sources)}</p>`:''}<p class="fuel-note">유류할증료: ${c.fuel?won(c.fuel.value)+' · '+esc(c.fuel.status):'미확인'} ${evidence(c.fuel?.sources)}<br>포함액은 상품가에 이미 들어 있어 다시 더하지 않습니다. 향후 변동액은 확인 후 기타 예산에 한 번만 입력하세요.</p><label class="per-product-budget">이 상품에만 더할 예상액 (1인·원)<input type="number" min="0" max="10000000" step="1000" inputmode="numeric" data-product-extra="${id}" value="${esc(state.productExtras[id]??0)}" aria-label="${esc(label(c))} 상품별 추가 예상액"></label><div class="assumption-note">${calc.unresolved.length?'미확인 비용: '+esc(calc.unresolved.join(' · '))+'. ':''}포함 유류·세금은 중복 합산하지 않습니다. 식비·옵션·향후 유류 변동·현지 추가비용을 모두 확정한 총액이 아닙니다.</div></article>`;}).join('');$('#budgetError').textContent=unique(errors).join(' ');renderBudgetRanking(ids);guideUI?.updateBudget();}
function renderBudgetRanking(ids){
 const rows=ids.map(id=>{const c=cardById[id];return c?{c,calc:calculateBudget(c,{...state.budget,productExtra:state.productExtras[id]??0})}:null;}).filter(r=>r&&r.calc.valid);
 if(rows.length<2){$('#budgetRanking').innerHTML=`<div class="ranking-hint">비교 상품을 2개 이상 담으면 <strong>추가경비까지 더한 순위</strong>를 막대로 보여드려요.</div>`;return;}
 rows.sort((a,b)=>a.calc.estimateKRW-b.calc.estimateKRW);const low=rows[0].calc.estimateKRW,high=rows.at(-1).calc.estimateKRW;const anyPending=rows.some(r=>r.calc.currencyConversionPending);
 const priceOrder=[...rows].sort((a,b)=>a.c.price-b.c.price).map(r=>r.c.id);const reordered=rows.some((r,i)=>r.c.id!==priceOrder[i]);
 $('#budgetRanking').innerHTML=`<div class="block-head"><h3>${anyPending?'엔화를 제외한 원화 부분합':'추가경비까지 더하면'}</h3><p>${rows[0].calc.people}인 · 같은 가정 적용. ${reordered?'<strong>표시가 순서와 총경비 순서가 달라집니다.</strong>':'표시가 순서와 총경비 순서가 같습니다.'}</p></div><ol class="rank-list">${rows.map((r,i)=>{const {c,calc}=r;const share=Math.max(4,Math.round(calc.base/high*100)),extra=Math.max(0,Math.round((calc.estimateKRW-calc.base)/high*100));return `<li style="--agency-color:${agencyColor(c.agency)}"><div class="rank-top"><span class="rank-no">${i+1}</span><span class="rank-name">${esc(label(c))}</span><b>${won(calc.estimateKRW)}</b></div><div class="rank-bar" role="img" aria-label="상품가 ${won(calc.base)}, 추가 ${won(calc.estimateKRW-calc.base)}"><span class="bar-base" style="width:${share}%"></span><span class="bar-extra" style="width:${extra}%"></span></div><div class="rank-meta"><span>${i===0?(anyPending?'원화 부분합 최저':'입력 조건에서 가장 적음'):'+'+won(calc.estimateKRW-low)}</span>${calc.currencyConversionPending?`<span class="warn">+ ${number(calc.yenTotal)}엔 별도</span>`:''}${calc.unresolved.length?`<span class="warn">미확인 비용 ${calc.unresolved.length}건</span>`:''}</div></li>`;}).join('')}</ol><div class="rank-legend"><span><i class="bar-base"></i>상품 표시가</span><span><i class="bar-extra"></i>가이드비·1인실·내 가정</span></div>${anyPending?'<p class="fine-print warn-text">엔화 비용은 환율을 입력하기 전까지 순위 합계에 들어가지 않습니다. 왼쪽에 가정 환율을 넣으면 함께 계산됩니다.</p>':''}`;
}

async function renderDetail(){const version=++detailVersion;$('#detailProduct').value=state.detailId;$('#detailPanel').innerHTML='<div class="loading">선택 상품을 살펴보고 있어요.</div>';const p=await getProduct(state.detailId);if(version!==detailVersion)return;const c=cardById[p.comparison_id];$('#detailSummary').innerHTML=`<div class="detail-overview"><div>${badge(c.agency)} <span class="product-id">${esc(label(c))} · ${esc(c.code)}</span><h3>${esc(c.name)}</h3><p class="detail-date">${esc(c.departure)} → ${esc(c.return)} · ${esc(c.duration)} · ${esc(c.airline)}</p></div><div><div class="detail-price">${won(c.price)}<div class="cell-status">성인 1인 표시가</div></div><button class="button primary" data-action="select" data-id="${c.id}">+ 비교에 담기</button></div></div>`;
 document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===state.detailTab));b.tabIndex=b.dataset.tab===state.detailTab?0:-1;});
 const renderers={itinerary:renderItinerary,hotel:renderHotels,meal:renderMeals,terms:renderTerms,questions:renderQuestions,sources:renderSources};$('#detailPanel').innerHTML=(renderers[state.detailTab]||renderItinerary)(p);}
function renderAdvice(p){return `<div class="advice-grid"><div class="advice-card"><h3>이 상품에서 확인한 조건</h3><ul>${p.advice.advantages.map(a=>`<li>${esc(a.text)} ${evidence(a.sources)}</li>`).join('')}</ul></div><div class="advice-card caution"><h3>예약 전에 짚어볼 점</h3><ul>${p.advice.cautions.map(a=>`<li>${esc(a.text)} ${evidence(a.sources)}</li>`).join('')}</ul></div></div>`;}
function dayPhotos(day,p){const names=day.sites.map(s=>s.name);if(p.comparison_id==='F27')return [];return catalog.photos.filter(photo=>photo.kind==='site'&&photo.tags.some(tag=>names.includes(tag))).slice(0,3);}
function renderItinerary(p){return renderAdvice(p)+p.days.map((d,i)=>{const photos=dayPhotos(d,p);return `<details class="day-card" ${i===0?'open':''}><summary><span class="day-number">${d.day}</span>${photos[0]?`<img class="day-thumb" src="${esc(photos[0].path)}" alt="" loading="lazy">`:''}<span class="day-caption"><strong>${d.day}일차 · ${esc(d.date.value||'날짜 미확인')}</strong><span>${p.comparison_id==='F27'?'자유일정 · 추천 관광지는 포함 관광이 아닙니다':esc(d.sites.map(s=>s.name).join(' · ')||'항공·숙박 및 자유시간 확인')}</span></span><span class="disclosure-arrow" aria-hidden="true">⌄</span></summary><div class="day-content">${photos.length?`<div class="day-gallery">${photos.map(photo=>`<figure>${photoButton(photo)}<figcaption>${esc(photo.label)} · PDF 참고사진</figcaption></figure>`).join('')}</div>`:'<div class="photo-placeholder">이 일차에 연결할 수 있는 사진 미확인 · 원문 일정은 아래에서 확인하세요</div>'}<div class="tour-tags">${d.sites.map(s=>`<span class="tour-pill">${esc(s.name)} ${evidence(s.sources,'근거')}</span>`).join('')||'<span class="soft-note">개별 관광지 기재 미확인</span>'}</div><details class="site-notes"><summary>관광지 설명 원문 펼치기</summary>${d.sites.map(s=>`<p><strong>${esc(s.name)}</strong><br>${esc(sourceText(p,s.sources,2)||'상세 설명 미확인')} ${evidence(s.sources)}</p>`).join('')||'<p>개별 관광지 설명 미확인</p>'}</details><div class="meal-grid">${mealBox(d.meals.breakfast,'조식')}${mealBox(d.meals.lunch,'중식')}${mealBox(d.meals.dinner,'석식')}</div><h4 style="font-size:12px;margin:15px 0 8px">이동과 관광시간</h4>${d.transport.segments.length?`<ul class="movement-list">${d.transport.segments.map(s=>`<li><span>${esc(s.segment.value)} ${evidence(s.sources,'근거')}</span><b>${esc(s.display_duration)} · ${esc(s.mode.value||'이동수단 미확인')}</b></li>`).join('')}</ul>`:'<p class="soft-note">명시 이동 구간·이동시간 미확인</p>'}<p class="info-note">하루 전체 이동시간 미확인 · 하루 관광시간 미확인${d.transport.stated_segments_partial_sum_minutes!==null?`<br>명시 구간의 부분합만 ${number(d.transport.stated_segments_partial_sum_minutes)}분입니다. 전체 이동시간이 아닙니다.`:''}</p>${d.hotel.candidates.length?`<p class="soft-note"><strong>이날의 예정호텔</strong> ${esc(d.hotel.candidates.map(h=>h.name.value).join(' / '))}</p>`:''}${d.free_time.length?`<details><summary class="soft-note">자유시간·자유관광 원문 안내</summary><ul class="raw-list">${d.free_time.map(x=>`<li>${esc(x.value)} ${evidence(x.sources)}</li>`).join('')}</ul></details>`:''}</div></details>`;}).join('')+`<p class="fine-print">관광지별 입장료의 일반 포함정책과 개별 유료 예외는 ‘포함·규정’에서 확인하세요. 사진은 다른 상품 PDF의 같은 관광지 참고사진일 수 있으며 확대 창에 정확한 출처가 표시됩니다.</p>`;}
function mealBox(meal,name){return `<div class="meal-box"><strong>${name}</strong><p>${esc(meal.value||'미확인')}</p><div class="cell-status ${statusClass(meal.status)}">${esc(meal.status)}</div>${evidence(meal.sources)}</div>`;}
// 이름 일부만 겹치는 다른 호텔(예: 그랜드 머큐어 ≠ 머큐어)에는 사진을 붙이지 않는다.
const photoExclude={'F26-p19-i5':['그랜드']};
function hotelPhoto(names){const cleaned=names.filter(Boolean).map(n=>n.replace(/\s/g,''));return catalog.photos.find(p=>p.kind==='hotel'&&p.tags.some(tag=>cleaned.some(n=>n.includes(tag)&&!(photoExclude[p.id]||[]).some(x=>n.includes(x)))));}
function renderHotels(p){return '<div class="info-note">호텔 후보별 위치·성급·온천·객실은 별도로 확인해야 합니다. 일차별 시설 기재를 대체호텔 전체의 보장 조건으로 표시하지 않습니다.</div>'+p.days.slice(0,3).map(d=>{const h=d.hotel;const names=h.candidates.map(x=>x.name.value);const photo=hotelPhoto(names);return `<article class="hotel-day"><h3>${d.day}박째 · 예정호텔과 대체 후보</h3><div class="hotel-layout"><div>${photo?photoButton(photo):'<div class="photo-placeholder">이 호텔의 사진 미확인</div>'}${photo?`<p class="fine-print">${esc(photo.label)} · 실제 배정 보장 아님</p>`:''}</div><div class="hotel-list">${h.candidates.map(c=>`<div class="hotel-option"><strong>${esc(c.name.value)}</strong><p>위치: ${esc(Array.isArray(c.city?.value)?c.city.value.join(' / '):'미확인')} · 성급: ${esc(c.grade.value||'미확인')}</p><span class="tag gray">예정 · 확정 전</span> ${evidence(unique([...c.name.sources,...c.grade.sources,...(c.city?.sources||[])]))}${c.additional_alternatives_count?`<p>원문에 추가 후보 ${c.additional_alternatives_count}개가 기재되어 있습니다. 이름·세부조건은 원문 목록 확인이 필요합니다.</p>`:''}</div>`).join('')||'<p>예정호텔 미확인</p>'}</div></div><div class="facility-grid"><div><b>온천 안내</b><span>${esc(facilityText(h.onsen_status,'온천'))} ${evidence(h.onsen_status?.sources,'근거')}</span></div><div><b>대욕장</b><span>${esc(facilityText(h.public_bath_status,'대욕장'))} ${evidence(h.public_bath_status?.sources,'근거')}</span></div><div><b>노천탕</b><span>${esc(facilityText(h.open_air_bath_status,'노천탕'))} ${evidence(h.open_air_bath_status?.sources,'근거')}</span></div></div><div class="room-notes"><strong>해당 일차의 객실 원문 조건</strong><br>${h.room_conditions.length?h.room_conditions.slice(0,5).map(x=>`${esc(x.value)} ${evidence(x.sources)}`).join('<br>'):'객실 타입·배정 조건 미확인'}</div></article>`;}).join('');}
function renderMeals(p){const mealphoto=catalog.photos.find(photo=>photo.kind==='meal'&&photo.tags.includes(p.comparison_id));return `<div class="info-note">‘현지식’만 기재된 식사의 메뉴는 미확인입니다. 자유식 현금 지원은 정해진 메뉴 포함과 구별하고, 미확인 식사를 불포함으로 바꾸지 않습니다.</div>${mealphoto?`<div class="day-gallery"><figure>${photoButton(mealphoto)}<figcaption>${esc(mealphoto.label)} · 실제 제공 메뉴는 변경 가능</figcaption></figure></div>`:''}<div class="table-scroll" tabindex="0" aria-label="날짜별 식사표"><table class="simple-table"><thead><tr><th scope="col">일차</th><th scope="col">조식</th><th scope="col">중식</th><th scope="col">석식</th></tr></thead><tbody>${p.days.map(d=>`<tr><th scope="row">${d.day}일차<br><small>${esc(d.date.value||'미확인')}</small></th>${['breakfast','lunch','dinner'].map(key=>{const m=d.meals[key];return `<td><p>${esc(m.value||'미확인')}</p><span class="tag ${m.status==='포함'?'green':m.status==='불포함'?'amber':'gray'}">${esc(m.status)}</span>${m.menu_tags?.length?`<p class="soft-note">${esc(m.menu_tags.join(' · '))}</p>`:''}${evidence(m.sources)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`;}
function renderTerms(p){const c=cardById[p.comparison_id];const fuel=p.costs.fuel_surcharge;const s=p.costs.single_room.amount;return `<div class="panel-card"><h3>포함·불포함과 별도 비용</h3><dl class="facts-list"><dt>가이드·기사 경비</dt><dd>${esc(guideText(c))} ${evidence(p.costs.guide_driver.sources)}</dd><dt>1인실 사용료</dt><dd>${s.value?number(s.value.amount)+' '+s.value.currency:'미확인'} ${evidence(s.sources)}${p.costs.single_room.conflict?`<p class="warn-text">${esc(p.costs.single_room.conflict.note)} ${evidence(p.costs.single_room.conflict.sources)}</p>`:''}</dd><dt>유류할증료</dt><dd>${fuel.value===null?'금액 미확인':won(fuel.value)} · ${esc(fuel.status)}${fuel.components?' · '+esc(fuel.components):''} ${evidence(fuel.sources)}<br><small>원문 변동 조건을 별도로 확인해 주세요.</small></dd><dt>제세공과금</dt><dd>${p.costs.taxes.value===null?'개별 금액 미확인':won(p.costs.taxes.value)} ${evidence(p.costs.taxes.sources)}</dd><dt>위탁수하물</dt><dd>${esc(p.original_fields.checked_baggage.value||'상품 적용 허용량 미확인')} ${evidence(p.original_fields.checked_baggage.sources)}</dd><dt>관광지 입장료</dt><dd>일반 포함 정책과 개별 유료 예외를 함께 확인해야 합니다. 무료입장이라는 뜻은 아닙니다. ${evidence(p.tour_admission.global_policy.sources)}</dd><dt>선택관광</dt><dd>${esc(p.optional_tours.status)} · ${p.optional_tours.status==='선택 가능'?'개별 이름·가격 미확인':'안내 원문 확인'} ${evidence(p.optional_tours.sources)}</dd><dt>쇼핑센터</dt><dd>${p.shopping.count.value===null?'횟수 미확인':p.shopping.count.value+'회'} · 방문 의무 ${esc(p.shopping.visit_obligation.value||'미확인')}<br>구매 의무 ${esc(p.shopping.purchase_obligation.value||'미확인')} ${evidence([...p.shopping.count.sources,...p.shopping.visit_obligation.sources,...p.shopping.purchase_obligation.sources])}</dd></dl>${p.tour_admission.known_paid_exceptions.length?`<details><summary>추가 유료 항목 원문</summary><ul class="raw-list">${p.tour_admission.known_paid_exceptions.map(x=>`<li>${esc(x.text)} ${evidence(x.sources)}</li>`).join('')}</ul></details>`:''}</div><div class="panel-card"><h3>예약과 취소</h3><dl class="facts-list"><dt>적용 약관</dt><dd>${esc(p.terms.type.value)} ${evidence(p.terms.type.sources)}</dd><dt>예약금</dt><dd>${p.terms.deposit.value===null?'미확인':won(p.terms.deposit.value)} ${evidence(p.terms.deposit.sources)}</dd><dt>최소 출발인원</dt><dd>${p.minimum_departure_people.value===null?'미확인':p.minimum_departure_people.value+'명'} ${evidence(p.minimum_departure_people.sources)}</dd><dt>취소 규정 상태</dt><dd>${esc(p.terms.cancellation_status)} ${evidence(p.terms.sources)}</dd></dl><p class="info-note">취소수수료는 실제 적용 약관과 예약·발권 시점에 따라 달라질 수 있습니다. 빠진 취소구간을 일반 규정으로 보완하지 않았습니다.</p><details><summary>기재된 취소수수료 원문 펼쳐보기</summary><ul class="raw-list">${p.terms.cancellation_rules.length?p.terms.cancellation_rules.map(x=>`<li>${esc(x.text)} ${evidence(x.sources)}</li>`).join(''):'<li>여행 취소의 단계별 수수료 미확인. 쇼핑 반품·환불 규정을 여행 취소 규정으로 취급하지 않습니다.</li>'}</ul></details><details><summary>예약금·변경·추가요금 조건 펼쳐보기</summary><div class="raw-rules">${esc(sourceText(p,unique([...p.terms.deposit_conditions.sources,...p.terms.changes.sources,...p.costs.other_cost_conditions_sources]),28)||'미확인')}</div></details></div>`;}
function questionText(p){const c=cardById[p.comparison_id];const hotels=p.days.slice(0,3).map(d=>`${d.day}박째 ${d.hotel.candidates.map(h=>h.name.value).join(' / ')}`).join('\n');const excluded=p.days.flatMap(d=>Object.entries(d.meals).filter(([,m])=>m.status==='불포함').map(([key,m])=>`${d.day}일차 ${({breakfast:'조식',lunch:'중식',dinner:'석식'})[key]} ${m.value}`));const problems=[...p.source_issues,...p.comparison_issues].filter(i=>i.type==='conflict'||i.field==='travel_cancellation');const references=unique([...(p.terms.sources||[]),...p.costs.guide_driver.sources]).slice(0,4).map(id=>p.source_index[id]).filter(Boolean).map(s=>`${s.file_name} ${s.page}페이지`).join(' / ');return `${c.agency} 담당자님께 문의드립니다.\n\n상품코드: ${c.code}\n출발일: ${c.departure} / ${c.duration}\nPDF 표시가: 성인 1인 ${won(c.price)} (현재가·최종가 확인 요청)\n\n1. 이 출발일의 현재 예약 가능 여부와 성인 1인 최종 결제금액을 알려주세요. 유류할증료·세금의 포함액과 추가 변동 가능액도 구분해 주세요.\n\n2. 아래 예정호텔 중 날짜별 확정 호텔과 위치, 객실 타입·침대·전망·2인/3인실 조건을 알려주세요.\n${hotels}\n온천·대욕장·노천탕의 실제 이용 가능 여부, 추가요금·운영시간도 후보별로 확인 부탁드립니다.\n\n3. ${guideText(c)}로 기재되어 있습니다. 성인/아동별 적용 단위와 현지 필수비용을 모두 알려주세요. 1인실·호텔 변경 시 추가요금도 확인 부탁드립니다.\n\n4. 식사 메뉴와 특식·뷔페·게요리·주류 무제한 조건을 확인해 주세요. ${excluded.length?'다음 불포함 식사의 예상 비용과 자유식 지원 여부도 알려주세요: '+excluded.join(' / '):'미기재 식사는 제공 여부를 확인 부탁드립니다.'}\n\n5. 쇼핑센터 ${c.shopping===null?'횟수 미확인':c.shopping+'회'} 조건에서 방문 이탈이 가능한가요? 구매하지 않아도 불이익이 없나요? 선택관광은 ${p.optional_tours.status}으로 표시되어 있는데, 각 항목의 이름·통화·가격과 미참가 시 대기·이동 조건을 알려주세요.\n\n6. 일정상 입장료 포함 범위와 별도 유료 체험·시음·교통비를 구분해 주세요. 주요 구간별 버스 탑승시간과 실제 관광시간도 알려주세요.\n\n7. 이 상품에 실제 적용되는 약관, 예약금 납부기한, 발권 후 변경·취소료, 출발 전 날짜별 취소수수료를 서면으로 안내해 주세요.${problems.length?' 아래 원문 확인 사항도 함께 답변 부탁드립니다:\n'+problems.slice(0,4).map(i=>'· '+i.message).join('\n'):''}\n\n8. 최소출발인원 ${p.minimum_departure_people.value===null?'미확인':p.minimum_departure_people.value+'명'} 조건과 실제 행사 인원·합류 여부, 인솔자·가이드 운영을 알려주세요.\n\n확인 자료: ${references||p.file_name}\n감사합니다.`;}
function renderQuestions(p){return `<div class="panel-card"><h3>여행사에 물어볼 질문을 준비했어요</h3><p class="soft-note">선택한 상품의 호텔·식사·경비·원문 충돌을 반영한 초안입니다. 편집 후 복사해 사용하세요. 자동으로 전송하지 않습니다.</p><textarea class="question-text" id="questionText" aria-label="여행사 문의 질문">${esc(questionText(p))}</textarea><div class="question-actions"><span class="soft-note">${esc(p.product_code.value)} · ${esc(p.departure_date.value)}</span><button class="button primary" data-action="copy-questions">질문 전체 복사 ⧉</button></div></div>`;}
function renderSources(p){const issues=[...p.source_issues,...p.comparison_issues];return `<div class="panel-card"><h3>원본과 정보 추적</h3><p class="source-summary">원본 파일: <strong>${esc(p.file_name)}</strong><br>페이지 번호는 PDF의 실제 페이지를 1부터 셉니다.<br><code>SHA-256: ${esc(p.original_sha256)}</code></p>${p.original_pdf?`<a class="button quiet" href="${esc(p.original_pdf)}" target="_blank" rel="noopener">원본 PDF 열기 ↗</a>`:'<p class="fine-print">이 가벼운 배포본에는 원본 PDF 305MB를 포함하지 않았습니다. 파일명·페이지·인용문으로 원본을 추적할 수 있습니다.</p>'}<div class="source-search"><input id="detailSourceQuery" type="search" placeholder="이 상품의 원문 근거 검색 (호텔·식사·취소 등)" aria-label="상품 원문 검색"><button class="button quiet" data-action="search-detail-source">근거 검색</button></div><button class="text-link" data-action="all-sources" data-id="${p.comparison_id}">페이지별 원문 근거 찾아보기 ↗</button></div><div class="panel-card"><h3>확인 필요 사항 ${issues.length}건</h3><p class="soft-note">원문 누락·상충·적용 여부·OCR 미검증을 구분해 보존했습니다. 정보가 없다는 사실을 무료 또는 없음으로 해석하지 않습니다.</p>${issues.map(i=>`<article class="issue-item"><span class="tag amber">${esc(i.type)}</span><p>${esc(i.message)}</p>${evidence(i.sources)}</article>`).join('')||'<p>기록된 확인 필요 사항 없음</p>'}</div>`;}
function renderInsights(){const titles=['같은 홋카이도라도, 실제 코스부터','가능한 기간에서 고른 출발일별 후보','호텔 위치·성급·온천은 별개 조건','한 끼의 메뉴와 포함 범위까지','명시된 이동 구간만 숫자로','쇼핑·선택관광·별도 경비까지','예약금 환불과 취소 규정 확인'];$('#insightGrid').innerHTML=differences.seven.map((x,i)=>`<details class="insight-card"><summary><span class="insight-number">0${i+1}</span><span>${titles[i]}</span><span style="margin-left:auto;color:#9aa28f" aria-hidden="true">+</span></summary><p>${esc(i===1?'출발일 차이는 비교를 막는 조건이 아닙니다. 여행 가능한 기간에서 골라둔 후보를 함께 비교하되, 항공시각·가격에 담긴 호텔·식사·경비 차이를 분리해 봅니다.':x.explanation.replaceAll(/F\d{2}/g,id=>cardById[id]?label(cardById[id]):id))}</p>${evidence(x.sources)}</details>`).join('');}
async function openEvidence(ids,{file=null,query=''}={}){sourceView={ids:unique(ids||[]),file,query,limit:25};$('#sourceContent').innerHTML='<div class="loading">해당 원문 근거를 불러오고 있습니다.</div>';const dlg=$('#sourceDialog');if(!dlg.open)dlg.showModal();const fids=unique(file?[file]:sourceView.ids.map(id=>id.split('-')[0]).filter(id=>cardById[id]));await Promise.all(fids.map(getProduct));await renderEvidence();}
async function renderEvidence(){const fids=unique(sourceView.file?[sourceView.file]:sourceView.ids.map(s=>s.split('-')[0]));const products=await Promise.all(fids.map(getProduct));const refs=Object.assign({},...products.map(p=>p.source_index));let ids=sourceView.file?Object.keys(refs):sourceView.ids;const q=(sourceView.query||'').toLocaleLowerCase('ko');if(q)ids=ids.filter(id=>refs[id]&&(`${refs[id].quote} ${refs[id].page} ${refs[id].file_name}`).toLocaleLowerCase('ko').includes(q));const entries=ids.map(id=>[id,refs[id]]).filter(([,entry])=>entry);$('#sourceContent').innerHTML=`<p class="soft-note">${sourceView.file?esc(cardById[sourceView.file].name):'선택한 정보의 근거'} · ${entries.length}개 인용문</p><div class="source-search"><input id="sourceQuery" type="search" aria-label="원문 인용문 검색" placeholder="단어 또는 페이지로 검색" value="${esc(sourceView.query||'')}"><button class="button quiet" data-action="source-search">검색</button></div>${entries.slice(0,sourceView.limit).map(([id,s])=>`<article class="source-entry"><div class="source-location">${esc(s.file_name)} · ${s.page}페이지</div><blockquote>${esc(s.quote)}</blockquote><small>${esc(id)} · 추출 줄 ${s.line??'미확인'} · ${esc(s.layer)} 레이어</small></article>`).join('')||'<p class="empty-state">일치하는 근거가 없습니다. 다른 단어로 검색해 주세요.</p>'}${entries.length>sourceView.limit?'<button class="button quiet" data-action="more-evidence">근거 25개 더 보기</button>':''}<p class="fine-print">추출 문장은 원본의 표 배치와 다를 수 있습니다. 예정·조건부·원문 충돌은 함께 확인해 주세요.</p>`;}
function openPhoto(id,list=[id]){photoList=unique(list.filter(x=>catalog.photos.some(p=>p.id===x)));if(!photoList.includes(id))photoList=[id];photoIndex=photoList.indexOf(id);showPhoto();if(!$('#photoDialog').open)$('#photoDialog').showModal();}
function showPhoto(){const photo=catalog.photos.find(p=>p.id===photoList[photoIndex]);if(!photo)return;$('#photoContent').innerHTML=`<figure><img src="${esc(photo.path)}" alt="${esc(photo.label)}"><figcaption>${esc(photo.label)}<small>출처: ${esc(photo.file_name)} · ${photo.page}페이지</small><small>${esc(photo.note)}</small></figcaption></figure>`;$('#photoNav').hidden=photoList.length<2;$('#photoCounter').textContent=`${photoIndex+1} / ${photoList.length}`;}
function stepPhoto(step){if(photoList.length<2)return;photoIndex=(photoIndex+step+photoList.length)%photoList.length;showPhoto();}
function photoScope(button){const scope=button.closest('#heroVisual,.day-card,.night-block,#detailPanel,section,dialog')||document;return [...scope.querySelectorAll('[data-action="photo"]')].map(b=>b.dataset.photo);}
async function copyQuestions(){const value=$('#questionText')?.value;if(!value)return;try{await navigator.clipboard.writeText(value);toast('문의 질문을 복사했어요. 여행사에 직접 전달해 주세요.');}catch{const input=$('#questionText');input.focus();input.select();try{if(!document.execCommand('copy'))throw new Error();toast('문의 질문을 복사했어요.');}catch{toast('복사를 허용하지 않는 환경입니다. 선택된 질문을 직접 복사해 주세요.');}}}
function resetFilters(){for(const key of filterKeys)state[key]=initial[key];persist();initFilters();renderCards();}
function goDetail(id,tab='itinerary'){state.detailId=id;state.detailTab=tab;persist();renderDetail().catch(showError);$('#detail').scrollIntoView({behavior:'smooth'});}
function eventHandlers(){
 document.addEventListener('click',async event=>{const close=event.target.closest('[data-close]');if(close){$('#'+close.dataset.close).close();return;}const button=event.target.closest('[data-action]');if(!button)return;const {action,id}=button.dataset;try{if(action==='select')selectProduct(id);else if(action==='remove')changeSelection(state.selected.filter(x=>x!==id));else if(action==='detail')goDetail(id);else if(action==='agency'){state.agency=button.dataset.agency;persist();initFilters();renderCards();}else if(action==='reset')resetFilters();else if(action==='pair'){const pair=differences.pairs.find(p=>p.pair_id===button.dataset.pair);if(pair){state.diffOnly=true;$('#differencesOnly').checked=true;changeSelection([pair.left_id,pair.right_id]);$('#compare').scrollIntoView({behavior:'smooth'});}}else if(action==='evidence')await openEvidence(button.dataset.sources.split(','));else if(action==='photo')openPhoto(button.dataset.photo,photoScope(button));else if(action==='photo-step')stepPhoto(Number(button.dataset.step));else if(action==='route'){state.route=button.dataset.route;persist();syncFilterValues();renderCards();if(button.classList.contains('route-card'))$('#browse').scrollIntoView({behavior:'smooth'});}else if(action==='pick')applyPick(JSON.parse(button.dataset.apply));else if(action==='clear-filter'){const key=button.dataset.key;state[key]=initial[key];persist();initFilters();renderCards();}else if(action==='people-preset'){state.budget.people=button.dataset.people;state.budget.singles=button.dataset.singles;persist();syncBudgetValues();renderBudget();}else if(action==='help')$('#helpDialog').showModal();else if(action==='copy-questions')await copyQuestions();else if(action==='all-sources')await openEvidence([],{file:id});else if(action==='search-detail-source')await openEvidence([],{file:state.detailId,query:$('#detailSourceQuery').value});else if(action==='source-search'){sourceView.query=$('#sourceQuery').value;sourceView.limit=25;await renderEvidence();}else if(action==='more-evidence'){sourceView.limit+=25;await renderEvidence();}}catch(error){showError(error);}});
 $('#searchInput').addEventListener('input',e=>{state.search=e.target.value;persist();renderCards();});
 for(const [id,key]of [['routeFilter','route'],['dateFilter','date'],['shoppingFilter','shopping'],['guideFilter','guide'],['dinnerFilter','dinner'],['sortSelect','sort']])$('#'+id).addEventListener('change',e=>{state[key]=e.target.value;persist();renderCards();});
 $('#onsenFilter').addEventListener('change',e=>{state.onsen=e.target.checked;persist();renderCards();});$('#maxPrice').addEventListener('input',e=>{state.maxPrice=Number(e.target.value);$('#maxPriceLabel').textContent=state.maxPrice>=2600000?'전체':won(state.maxPrice);persist();renderCards();});$('#resetFilters').addEventListener('click',resetFilters);$('#clearSelection').addEventListener('click',()=>changeSelection([]));$('#goCompare').addEventListener('click',()=>$('#compare').scrollIntoView({behavior:'smooth'}));
 $('#differencesOnly').addEventListener('change',e=>{state.diffOnly=e.target.checked;persist();renderCompare().catch(showError);});$('#compareCategory').addEventListener('change',e=>{state.category=e.target.value;persist();renderCompare().catch(showError);});$('#budgetProduct').addEventListener('change',e=>{state.budgetProduct=e.target.value;persist();renderBudget();});$('#detailProduct').addEventListener('change',e=>goDetail(e.target.value,state.detailTab));
 $('#budgetForm').addEventListener('submit',e=>e.preventDefault());$('#budgetForm').addEventListener('input',e=>{const key=budgetIds[e.target.id];if(key){state.budget[key]=e.target.value;persist();renderBudget();}});
 $('#budgetResults').addEventListener('input',e=>{const id=e.target.dataset.productExtra;if(!id)return;state.productExtras[id]=e.target.value;persist();const focusPosition={id,value:e.target.value};renderBudget();const next=document.querySelector(`[data-product-extra="${focusPosition.id}"]`);if(next)next.focus({preventScroll:true});});
 document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{state.detailTab=button.dataset.tab;persist();renderDetail().catch(showError);}));
 $('.detail-tabs').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...document.querySelectorAll('[data-tab]')];let i=tabs.findIndex(t=>t.getAttribute('aria-selected')==='true');i=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].click();tabs[i].focus();});
 $('#helpButton').addEventListener('click',()=>$('#helpDialog').showModal());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
 let touchX=null;$('#photoDialog').addEventListener('touchstart',e=>{touchX=e.touches[0].clientX;},{passive:true});$('#photoDialog').addEventListener('touchend',e=>{if(touchX===null)return;const dx=e.changedTouches[0].clientX-touchX;touchX=null;if(Math.abs(dx)>45)stepPhoto(dx<0?1:-1);});
 document.addEventListener('keydown',e=>{if($('#photoDialog').open&&(e.key==='ArrowLeft'||e.key==='ArrowRight')){e.preventDefault();stepPhoto(e.key==='ArrowRight'?1:-1);return;}if(e.key==='Enter'&&e.target.id==='sourceQuery'){e.preventDefault();sourceView.query=e.target.value;renderEvidence().catch(showError);}else if(e.key==='Enter'&&e.target.id==='detailSourceQuery'){e.preventDefault();openEvidence([],{file:state.detailId,query:e.target.value}).catch(showError);}});
 document.addEventListener('error',event=>{if(event.target instanceof HTMLImageElement){const placeholder=document.createElement('div');placeholder.className='photo-placeholder';placeholder.textContent='사진을 불러오지 못했습니다. 원문 설명을 확인해 주세요.';event.target.replaceWith(placeholder);}},true);
}
async function start(){try{[catalog,differences]=await Promise.all([json('data/catalog.json'),json('data/differences.json')]);cardById=Object.fromEntries(catalog.cards.map(c=>[c.id,c]));
 groupById=Object.fromEntries(catalog.groups.map(g=>[g.route_group_id,g]));state.selected=unique(Array.isArray(state.selected)?state.selected:[]).filter(id=>cardById[id]).slice(0,4);if(!cardById[state.detailId])state.detailId='F05';if(!cardById[state.budgetProduct])state.budgetProduct='F05';if(!Object.hasOwn(agencyStyles,state.agency)&&state.agency!=='all')state.agency='all';if(!groupById[state.route]&&state.route!=='all')state.route='all';
 for(const c of catalog.cards)groupMin[c.group]=Math.min(groupMin[c.group]??Infinity,c.price);
 if(['date','shopping','guide','dinner'].some(k=>state[k]!=='all')||state.onsen||state.maxPrice<2600000)$('#moreFilters').open=true;
 initHero();renderSummary();initFilters();eventHandlers();renderCards();renderTray();renderBudget();renderInsights();$('#pairSuggestions').innerHTML=['P02','P07','P08','P05'].map(id=>{const pair=differences.pairs.find(p=>p.pair_id===id);return `<button class="pair-button" data-action="pair" data-pair="${id}">${esc(label(cardById[pair.left_id]))} ↔ ${esc(label(cardById[pair.right_id]))} ${id==='P02'?'· 쇼핑 차이':id==='P07'?'· 같은 가격, 다른 호텔':id==='P08'?'· 운영 조건 차이':'· 별도 경비 차이'}</button>`;}).join('');const shared=new URLSearchParams(location.search);if(shared.has('compare')){state.selected=unique((shared.get('compare')||'').split(',')).filter(id=>cardById[id]).slice(0,4);for(const key of ['agency','route','date','shopping','guide','dinner','search','sort'])if(shared.has(key))state[key]=shared.get(key);if(shared.has('maxPrice')){const n=Number(shared.get('maxPrice'));if(Number.isFinite(n)&&n>=1200000&&n<=2600000)state.maxPrice=n;}state.onsen=shared.get('onsen')==='1';if(!agencyStyles[state.agency])state.agency='all';if(!groupById[state.route])state.route='all';persist();initFilters();renderCards();renderTray();renderBudget();}await Promise.all([renderCompare(),renderDetail()]);guideUI=await initGuide({catalog,state,initial,getProduct,getFields,cell,esc,won,number,label,badge,evidence,photoButton,hotelPhoto,facilityText,changeSelection,selectProduct,sourceText,toast,showError,agencyColor});document.documentElement.dataset.ready='true';}catch(error){console.error(error);$('#loadError').hidden=false;$('#loadError').textContent='자료를 불러오지 못했습니다. index.html을 직접 더블클릭했다면 정적 미리보기 주소로 열어주세요. 실행 방법은 RUN.txt를 확인해 주세요.';$('#resultCount').textContent='자료 불러오기 실패';}}
start();

// Determine the current section from scroll position, including the hero above all sections.
// An intersection-only observer retained the last section after jumping back to the top.
let navFrame=0,currentSection='';
function updateSectionNav(){
 navFrame=0;const ids=['summary','autoCompare','browse','allCompare','compare','focusCompare','budget','detail','preferences','insights'];
 const threshold=($('.section-nav')?.getBoundingClientRect().bottom||0)+80;
 let id=ids[0];for(const candidate of ids){if(document.getElementById(candidate).getBoundingClientRect().top<=threshold)id=candidate;}
 if(id===currentSection)return;currentSection=id;
 document.querySelectorAll('.site-header nav a,.section-nav a').forEach(link=>{const active=link.hash==='#'+id;link.classList.toggle('active',active);if(active){link.setAttribute('aria-current','location');const bar=link.closest('.section-nav-inner');if(bar)bar.scrollTo({left:link.offsetLeft-bar.clientWidth/2+link.clientWidth/2,behavior:'smooth'});}else link.removeAttribute('aria-current');});
}
function scheduleSectionNav(){if(!navFrame)navFrame=requestAnimationFrame(updateSectionNav);}
addEventListener('scroll',scheduleSectionNav,{passive:true});addEventListener('resize',scheduleSectionNav);scheduleSectionNav();
